    if let Some((p, c)) = smt {
        placements.push((format!("2t same core {p}+{c}"), SweepPlacement::TwoT(smt)));
    }
    let depth_list: Vec<String> = DEPTHS.iter().map(|d| d.to_string()).collect();
    println!(
        "depth sweep: {} messages per cell, ns/msg at depths {}",
        commas(COUNT),
        depth_list.join(", ")
