        println!();
        let mut header = format!("| {label:<22} |");
        let mut sep = format!("|{}|", "-".repeat(24));
        for d in &depth_list {
            header.push_str(&format!(" {:>7} |", format!("d={d}")));
            sep.push_str(&format!("{}:|", "-".repeat(8)));
        }
        println!("{header}");
        println!("{sep}");
        for flavor in &STREAM_FLAVORS {
            let mut row = format!("| {:<22} |", flavor.name);
            for &depth in &DEPTHS {
